const fs = require('fs')
const path = require('path')
const ejs = require('ejs')

async function buildUI(root = path.resolve(__dirname, '..')) {
  const template = path.join(root, 'src/views/index.ejs')
  const html = await ejs.renderFile(template, {})
  fs.writeFileSync(
    path.join(root, 'src/index.html'),
    '<!-- Generated by npm run ui:build. Edit src/views/*.ejs instead. -->\n' + html
  )
  return html
}
if (require.main === module)
  buildUI().catch((error) => {
    console.error(error)
    process.exitCode = 1
  })
module.exports = { buildUI }
